import{_ as e,o,c as a,a5 as s}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"三种事件模型","description":"现代浏览器一共有三种事件模型。 DOM0 级模型 DOM0 模型不会传播，所以没有事件流的概念，但是现在有的浏览器支持以冒泡的方式实现，它可以在网页中直接定义监听函数，也可以通过 js 属性来指定监听函数。这种方式是所有浏览器都兼容的。 IE 事件模型 ： IE 事件模型的事件有。","frontmatter":{"title":"三种事件模型","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","浏览器与 Web API"],"description":"现代浏览器一共有三种事件模型。 DOM0 级模型 DOM0 模型不会传播，所以没有事件流的概念，但是现在有的浏览器支持以冒泡的方式实现，它可以在网页中直接定义监听函数，也可以通过 js 属性来指定监听函数。这种方式是所有浏览器都兼容的。 IE 事件模型 ： IE 事件模型的事件有。","sidebarWeight":46,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/DOM/事件/三种事件模型.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/04-浏览器与 Web API/事件/三种事件模型.md","filePath":"posts/JavaScript系统教程/04-浏览器与 Web API/事件/三种事件模型.md"}'),r={name:"posts/JavaScript系统教程/04-浏览器与 Web API/事件/三种事件模型.md"};function n(c,t,i,d,_,p){return o(),a("div",null,[...t[0]||(t[0]=[s('<div><h1 id="三种事件模型" tabindex="-1">三种事件模型 <a class="header-anchor" href="#三种事件模型" aria-label="Permalink to &quot;三种事件模型&quot;">​</a></h1><blockquote><p>本节目标：理解“三种事件模型”的核心思路，并能把它用于实际开发或面试表达。 ==现代浏览器一共有三种事件模型。====== <strong>DOM0</strong> <strong>级模型</strong> ==DOM0====模型不会传播，所以没有事件流的概念，但是现在有的浏览器支持以冒泡的方式实现，它可以在网页中直接定义监听函数，也可以通过== ==js== ==属性来指定监听函数。这种方式是所有浏览器都兼容的。== <strong>IE<strong><strong>事件模型</strong></strong>：</strong> ==IE====事件模型的事件有两个过程，事件处理阶段和事件冒泡阶段。事件处理阶段会首先执行目标元素绑定的监听事件。然后是事件冒泡阶段，冒泡指的是事件从目标元素冒泡到====document====，依次检查经过的节点是否绑定了事件监听函数，如果有则执行。这种模型通过== ==attachEvent== ==来添加监听函数，可以添加多个监听函数，会按顺序依次执行。====== <strong>DOM2</strong> <strong>级事件模型</strong> ==DOM2====级====事件模型的事件共有三个过程，第一个过程是事件捕获阶段。捕获指的是事件从====document====一直向下传播到目标元素，依次检查经过的节点是否绑定了事件监听函数，如果有则执行。后面两个阶段和====IE====事件模型的两个阶段相同。这种事件模型，事件绑定的函数是== ==addEventListener====，其中第三个参数可以指定事件是否在捕获阶段执行。==</p></blockquote></div>',1)])])}const m=e(r,[["render",n]]);export{g as __pageData,m as default};
